#pragma once
#include <juce_audio_processors/juce_audio_processors.h>
#include "ModelCodec.h"
#include "Controls.h"
struct LibraryEntry {juce::File file;juce::String name,category,tags;bool favourite=false;};
inline juce::File novaLibraryRoot(){
#if defined(NOVA_TEST_LIBRARY)
 static const auto root=juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("NovaSynth-Test-"+juce::Uuid().toString());return root;
#else
 return juce::File::getSpecialLocation(juce::File::userApplicationDataDirectory).getChildFile("NovaSynth");
#endif
}
inline std::vector<LibraryEntry> readPersonalLibrary(){std::vector<LibraryEntry> result;juce::Array<juce::File> files;novaLibraryRoot().getChildFile("Presets").findChildFiles(files,juce::File::findFiles,false,"*.novapreset");for(auto f:files){if(result.size()>=1000)break;auto xml=juce::XmlDocument::parse(f.withFileExtension("xml"));LibraryEntry e;e.file=f;e.name=xml?xml->getStringAttribute("name",f.getFileNameWithoutExtension()):f.getFileNameWithoutExtension();e.category=xml?xml->getStringAttribute("category","Personal"):"Personal";e.tags=xml?xml->getStringAttribute("tags"):"";e.favourite=xml&&xml->getBoolAttribute("favourite");result.push_back(e);}std::stable_sort(result.begin(),result.end(),[](auto& a,auto& b){return a.name.compareIgnoreCase(b.name)<0;});return result;}
inline bool writeLibraryInfo(const LibraryEntry& e){juce::XmlElement xml("NovaLibraryPreset");xml.setAttribute("name",e.name.substring(0,80));xml.setAttribute("category",e.category.substring(0,40));xml.setAttribute("tags",e.tags.substring(0,160));xml.setAttribute("favourite",e.favourite);return e.file.withFileExtension("xml").replaceWithText(xml.toString());}
inline bool decodePreviewPatch(const juce::MemoryBlock& data,nova::Params& p,std::shared_ptr<nova::SpectralModel>& model,std::shared_ptr<nova::ZoneBank>& bank){if(data.getSize()<1||data.getSize()>24*1024*1024)return false;auto xml=juce::AudioProcessor::getXmlFromBinary(data.getData(),static_cast<int>(data.getSize()));if(!xml||!xml->hasTagName("NovaSynth"))return false;auto tree=juce::ValueTree::fromXml(*xml);auto value=[&](const char* id,float fallback){auto child=tree.getChildWithProperty("id",id);float x=child.isValid()?static_cast<float>(child.getProperty("value",fallback)):fallback;return std::isfinite(x)?x:fallback;};float root=60,transpose=0;float* fields[]={&p.mix,&p.detune,&transpose,&p.sub,&p.noise,&p.fm,&p.cutoff,&p.resonance,&p.envAmount,&p.attack,&p.decay,&p.sustain,&p.release,&p.lfoRate,&p.lfoDepth,&p.drive,&p.delay,&p.delayTime,&p.feedback,&p.reverb,&p.spread,&p.master,&root,&p.fineTune,&p.chorus,&p.chorusRate,&p.room,&p.eqLow,&p.eqHigh,&p.spectralTime,&p.spectralTone,&p.residual,&p.tracking};for(size_t i=0;i<controlCount;++i)*fields[i]=std::clamp(value(controls[i].id,controls[i].initial),controls[i].minimum,controls[i].maximum);p.root=static_cast<int>(root);p.transpose=static_cast<int>(transpose);p.engine=std::clamp(static_cast<int>(value("synthengine",0)),0,4);p.waveA=std::clamp(static_cast<int>(value("wavea",1)),0,4);p.waveB=std::clamp(static_cast<int>(value("waveb",0)),0,4);p.unison=value("unison",0)>.5f;
 p.character=std::clamp(value("character",0),0.f,1.f);p.brightness=std::clamp(value("brightness",0),0.f,1.f);p.movement=std::clamp(value("movement",0),0.f,1.f);p.space=std::clamp(value("space",0),0.f,1.f);p.palette=std::clamp(static_cast<int>(value("palette",0)),0,6);p.velocityTone=std::clamp(value("velocitytone",0),0.f,1.f);p.touch=std::clamp(value("touch",0),0.f,1.f);p.modRate=std::clamp(value("modrate",1),.03f,15.f);p.presetTrim=std::clamp(value("presettrim",0),-12.f,36.f);p.boost=std::clamp(value("boost",0),-12.f,12.f);p.driveOn=value("driveOn",1)>.5f;p.chorusOn=value("chorusOn",1)>.5f;p.eqOn=value("eqOn",1)>.5f;p.delayOn=value("delayOn",1)>.5f;p.reverbOn=value("reverbOn",1)>.5f;for(int i=0;i<nova::partialCount;++i)p.partialGains[i]=std::clamp(value(("partial"+juce::String(i+1).paddedLeft('0',2)).toRawUTF8(),1),0.f,2.f);for(int i=0;i<4;++i){auto id="mod"+juce::String(i+1);p.routes[i].source=std::clamp(static_cast<int>(value((id+"source").toRawUTF8(),0)),0,6);p.routes[i].destination=std::clamp(static_cast<int>(value((id+"dest").toRawUTF8(),0)),0,4);p.routes[i].amount=std::clamp(value((id+"amount").toRawUTF8(),0),-1.f,1.f);}juce::MemoryBlock raw;auto encoded=tree.getProperty("partialModelV2",tree.getProperty("partialModelV1")).toString();if(encoded.isNotEmpty()){if(encoded.length()>60000||!raw.fromBase64Encoding(encoded))return false;model=std::make_shared<nova::SpectralModel>();if(!nova::decodeModel(raw.getData(),raw.getSize(),*model))return false;}encoded=tree.getProperty("zonesV1").toString();if(encoded.isNotEmpty()){if(encoded.length()>450000||!raw.fromBase64Encoding(encoded))return false;bank=std::make_shared<nova::ZoneBank>();if(!nova::decodeZones(raw.getData(),raw.getSize(),*bank))return false;}p.useZones=bank&&static_cast<bool>(tree.getProperty("multiEnabled",false));return p.engine!=1||(model&&model->valid())||p.useZones;}
